import {tasks,taskKinds,substrates,directions,today,dateOnly,addDays,due,formatDate,name,event,starterPlans,suggestedDays,interval,water,postponeCheck,finishTask,newPlant,uid} from './care.js';

const root=document.querySelector('#app'),sheetRoot=document.querySelector('#sheet-root'),toastRoot=document.querySelector('#toast-root');
const app={plants:[],rooms:[],preferences:{},tab:'today',detail:null,auth:null,services:{},undo:null,toastTimer:null,sticky:false,sheetStack:[]};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=esc;
const byId=id=>app.plants.find(p=>p.id===id);
const room=id=>app.rooms.find(r=>r.id===id);
const photo=id=>id?`/api/photos/${encodeURIComponent(id)}`:null;
const imageFor=p=>p.photoName?photo(p.photoName):(p.useReferenceImage&&/^https:\/\//.test(p.referenceImageURL||'')?p.referenceImageURL:null);
const display=p=>esc(name(p));
const substrateName=value=>({'Blumenerde':'Pflanzenerde','Lockerer Aroid-Mix':'Aroid-Mix'}[value]||value||'Pflanzenerde');
const short=(s,n=90)=>String(s||'').length>n?String(s).slice(0,n-1)+'…':String(s||'');
const select=(items,value)=>items.map(x=>`<option value="${attr(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('');
const card=(content,extra='')=>`<div class="card ${extra}">${content}</div>`;
const field=(label,html)=>`<div class="field"><label>${label}</label>${html}</div>`;
const button=(label,action,id='',cls='secondary')=>`<button type="button" class="btn ${cls}" data-action="${action}" data-id="${attr(id)}">${label}</button>`;
const empty=(message)=>`<div class="empty">${esc(message)}</div>`;
const section=(title,content,extra='')=>`<section class="section"><div class="section-head"><h2>${title}</h2>${extra}</div>${content}</section>`;
const icon=kind=>({today:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',plants:'<path d="M12 21v-9m0 5c-5 0-8-3-8-8 4 0 7 1 8 4m0 1c0-5 3-8 8-9 0 5-2 9-8 9"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="2"/><circle cx="15" cy="17" r="2"/>'})[kind];
const navIcon=kind=>`<svg class="symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icon(kind)}</svg>`;
async function api(path,method='GET',body=null,type='json'){
  const options={method,credentials:'same-origin',headers:{}};
  if(body!==null){if(type==='json'){options.headers['Content-Type']='application/json';options.body=JSON.stringify(body)}else{options.headers['Content-Type']=type;options.body=body}}
  const response=await fetch(path,options);let result;try{result=await response.json()}catch{result={error:'Antwort konnte nicht gelesen werden.'}}
  if(!response.ok)throw Error(result.error||'Anfrage fehlgeschlagen.');return result;
}
async function load(){const s=await api('/api/state');app.plants=s.plants;app.rooms=s.rooms;app.preferences=s.preferences||{};app.services=await api('/api/services/status').catch(()=>({}));applyTheme();render()}
function applyTheme(){const m=app.preferences.appearance||'system';document.documentElement.dataset.theme=m==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):m}
function toast(message,undo=false){clearTimeout(app.toastTimer);toastRoot.innerHTML=`<div class="toast"><span class="grow">${esc(message)}</span>${undo?'<button data-action="undo">Rückgängig</button>':''}<button data-action="clear-toast" aria-label="Schließen">×</button></div>`;app.toastTimer=setTimeout(()=>{toastRoot.innerHTML='';app.undo=null},4500)}
async function savePlant(p,message='Gespeichert'){await api(`/api/plants/${encodeURIComponent(p.id)}`,'PUT',p);const index=app.plants.findIndex(x=>x.id===p.id);if(index<0)app.plants.push(p);else app.plants[index]=p;render();if(message)toast(message)}
async function mutate(id,fn,label='Gespeichert'){const original=structuredClone(byId(id));if(!original)return;const next=structuredClone(original);fn(next);await savePlant(next,'');app.undo=original;toast(label,true)}
async function saveRoom(r){await api(`/api/rooms/${encodeURIComponent(r.id)}`,'PUT',r);const i=app.rooms.findIndex(x=>x.id===r.id);if(i<0)app.rooms.push(r);else app.rooms[i]=r;render();toast('Raum gespeichert')}
function shell(content){root.innerHTML=`<div class="topbar" id="sticky">${app.sticky?esc(app.detail?name(byId(app.detail)||{species:'Pflanze'}):({today:'Heute',plants:'Pflanzen',settings:'Einstellungen'}[app.tab])):''}</div><div class="shell">${content}</div><nav class="nav" aria-label="Hauptnavigation"><button class="${app.tab==='today'&&!app.detail?'active':''}" data-action="tab" data-id="today">${navIcon('today')}Heute</button><button class="${app.tab==='plants'||app.detail?'active':''}" data-action="tab" data-id="plants">${navIcon('plants')}Pflanzen</button><button class="${app.tab==='settings'&&!app.detail?'active':''}" data-action="tab" data-id="settings">${navIcon('settings')}Einstellungen</button></nav>`;const header=document.querySelector('header.page');if(header){const observer=new IntersectionObserver(entries=>{const sticky=!entries[0].isIntersecting;if(sticky!==app.sticky){app.sticky=sticky;document.querySelector('#sticky').textContent=sticky?(app.detail?name(byId(app.detail)||{species:'Pflanze'}):({today:'Heute',plants:'Pflanzen',settings:'Einstellungen'}[app.tab])):''}},{threshold:0});observer.observe(header)}}
function render(){if(!app.auth?.authenticated)return renderAuth();if(app.detail){const p=byId(app.detail);if(p)return shell(detailPage(p));app.detail=null}shell(app.tab==='plants'?plantsPage():app.tab==='settings'?settingsPage():todayPage())}
function renderAuth(){const first=app.auth?.firstAccount,open=app.auth?.registrationOpen;root.innerHTML=`<div class="auth">${card(`<p class="eyebrow">Dein grüner Alltag</p><h1>Pflanzenpflege</h1><p class="lead">${first?'Lege dein Konto an.':'Melde dich an, um deine Pflanzen zu sehen.'}</p><form id="auth-form" data-mode="${first?'register':'login'}">${field('Benutzername','<input name="username" autocomplete="username" required>')}${field('Passwort','<input type="password" name="password" autocomplete="'+(first?'new-password':'current-password')+'" minlength="'+(first?'10':'1')+'" required>')}${first&&!app.auth?.firstAccountServer?field('Einladungscode','<input name="invite" autocomplete="off" required>'):''}<div class="actions"><button class="btn" type="submit">${first?'Konto anlegen':'Anmelden'}</button></div></form>${!first&&open?'<div class="hr"></div><button class="btn secondary" data-action="register-form">Neues Konto anlegen</button>':''}${first&&!app.auth?.firstAccountServer?button('Zur Anmeldung','login-form','','ghost'):''}${!first?'<p class="small">Bei bestehenden Konten funktioniert auch die bisherige E-Mail-Adresse als Benutzername.</p>':''}`)}</div>`}
function title(eyebrow,heading,lead=''){return `<header class="page"><p class="eyebrow">${eyebrow}</p><h1>${heading}</h1>${lead?`<p class="lead">${lead}</p>`:''}</header>`}
function taskRow(p,task,watering=false){const id=attr(p.id),label=watering?(p.substrate==='Wasser'?'Wasserstand prüfen':'Erde prüfen'):task;return `<div class="taskrow"><button class="check" data-action="${watering?'water':'finish-task'}" data-id="${id}" data-task="${attr(task)}" aria-label="${esc(label)} erledigen"></button><div class="grow"><strong>${esc(label)}</strong><div class="small">${display(p)}</div></div>${watering?`<button class="btn tiny secondary" data-action="postpone" data-id="${id}">Zurückstellen</button>`:''}</div>`}
function todayPage(){const watering=app.plants.filter(p=>due(p.nextCheck)),planTasks=tasks.map(t=>({task:t,plants:app.plants.filter(p=>(p.taskPlans||[]).some(x=>x.task===t&&due(x.next)))})).filter(g=>g.plants.length),total=watering.length+planTasks.reduce((n,g)=>n+g.plants.length,0);let content=title('Dein Tag','Heute',total?`${total} ${total===1?'Aufgabe wartet':'Aufgaben warten'} auf dich.`:'Alles im grünen Bereich.');content+=card(`<p class="eyebrow">Heute im Blick</p><h2>${total?`${total} Aufgaben`:'Gut gepflegt'}</h2><p class="lead">${total?'Ein Haken genügt, wenn du eine Aufgabe erledigt hast.':'Deine Pflanzen brauchen heute nichts von dir.'}</p>`,'soft');if(watering.length)content+=section(watering.every(p=>p.substrate==='Wasser')?'Wasserstand prüfen':watering.some(p=>p.substrate==='Wasser')?'Erde & Wasser prüfen':'Erde prüfen',card(watering.map(p=>taskRow(p,'',true)).join('')));for(const group of planTasks)content+=section(esc(group.task),card(group.plants.map(p=>taskRow(p,group.task)).join('')));const upcoming=app.plants.filter(p=>!due(p.nextCheck)).sort((a,b)=>dateOnly(a.nextCheck).localeCompare(dateOnly(b.nextCheck))).slice(0,6);content+=section('Nächste Prüfungen',upcoming.length?card(upcoming.map(p=>`<div class="settingrow"><div class="grow"><strong>${display(p)}</strong><div class="small">${formatDate(p.nextCheck)}</div></div>${button('Öffnen','detail',p.id,'tiny secondary')}</div>`).join('')):empty('Noch keine Pflanzen angelegt.'),button('Pflanze hinzufügen','plant-form','','tiny'));return content}
function plantList(items){return items.length?card(items.map(p=>{const src=imageFor(p);return `<div class="plantrow" data-action="detail" data-id="${attr(p.id)}">${src?`<img class="plantthumb" src="${attr(src)}" alt="">`:'<div class="plantthumb seed">♣</div>'}<div class="grow"><strong>${display(p)}</strong>${p.nickname?`<div class="small">${esc(p.species)}</div>`:''}</div><span class="muted">›</span></div>`}).join('')):empty('Hier sind noch keine Pflanzen.')}
function plantsPage(){let content=title('Deine Sammlung','Pflanzen',`${app.plants.length} ${app.plants.length===1?'Pflanze':'Pflanzen'} in ${app.rooms.length} ${app.rooms.length===1?'Raum':'Räumen'}`);content+=`<div class="actions">${button('+ Pflanze','plant-form','','')}${button('+ Raum','room-form')}</div>`;for(const r of app.rooms){const items=app.plants.filter(p=>p.roomID===r.id);content+=section(esc(r.name),plantList(items),`<button class="btn tiny secondary" data-action="room-form" data-id="${attr(r.id)}" aria-label="${esc(r.name)} bearbeiten">⚙</button>`)}const unassigned=app.plants.filter(p=>!p.roomID||!room(p.roomID));content+=section('Ohne Raum',plantList(unassigned));return content}
function detailPage(p){
  const src=imageFor(p), r=room(p.roomID);
  const latest=[...(p.events||[])].filter(e=>e.kind==='Fortschritt').sort((a,b)=>b.date.localeCompare(a.date))[0];
  let content=title(r?esc(r.name):'Deine Pflanze',display(p),p.nickname?esc(p.species):'');
  content+=`<div class="detailtop">${button('← Pflanzen','back','','tiny secondary')}<span class="grow"></span>${button('Bearbeiten','plant-form',p.id,'tiny secondary')}</div>`;
  if(src)content+=`<img class="hero" src="${attr(src)}" alt="${display(p)}">`;
  const careRows=(p.taskPlans||[]).map(plan=>{
    const done=button('Erledigt','finish-task',p.id,'tiny secondary').replace('data-id=',`data-task="${attr(plan.task)}" data-id=`);
    return `<div class="settingrow"><div class="grow"><strong>${esc(plan.task)}</strong><div class="small">${formatDate(plan.next)}</div></div>${done}</div>`;
  }).join('');
  const waterRow=`<div class="settingrow"><div class="grow"><strong>${p.substrate==='Wasser'?'Wasserstand prüfen':'Erde prüfen'}</strong><div class="small">${formatDate(p.nextCheck)}</div></div>${p.substrate==='Wasser'?button('Geprüft','water',p.id,'tiny'):button('Gegossen','watering-choice',p.id,'tiny')}${due(p.nextCheck)?button('Zurückstellen','postpone',p.id,'tiny secondary'):''}</div>`;
  content+=section('Nächste Pflege',card(waterRow+careRows),button('Pflegeplan','care-plan',p.id,'tiny secondary'));
  const lightRows=`<div class="settingrow"><div class="grow">Raum</div><strong>${esc(r?.name||'Ohne Raum')}</strong></div><div class="settingrow"><div class="grow">Fenster</div><strong>${esc(p.windowDirection||'–')}${p.windowDistance!=null?`, ${esc(Math.round(p.windowDistance*100))} cm`:''}</strong></div><div class="settingrow"><div class="grow">Wachstumslicht</div><strong>${p.growLight?`${esc(p.lightHours||0)} h · ${esc(p.ppfd||0)} PPFD`:'Aus'}</strong></div><div class="settingrow"><div class="grow">Heizungsnähe</div><strong>${p.nearHeater?'Ja':'Nein'}</strong></div>`;
  content+=section('Standort & Licht',card(lightRows));
  content+=section('Topf & Substrat',card(`<div class="settingrow"><div class="grow">Durchmesser</div><strong>${esc(p.potDiameter)} cm</strong></div>${p.heightCM!=null?`<div class="settingrow"><div class="grow">Pflanzenhöhe</div><strong>${esc(p.heightCM)} cm</strong></div>`:''}<div class="settingrow"><div class="grow">Substrat</div><strong>${esc(substrateName(p.substrate))}</strong></div>`));
  if(p.careNotes){const notes=['sunlight','watering','fertilization','soil'].map((key,i)=>p.careNotes[key]?`<p><strong>${['Licht','Gießen','Düngen','Substrat'][i]}:</strong> ${esc(p.careNotes[key])}</p>`:'').join('');const light=p.careNotes.minLux!=null||p.careNotes.maxLux!=null?`<p><strong>Empfohlenes Licht:</strong> ${esc(p.careNotes.minLux??'–')}–${esc(p.careNotes.maxLux??'–')} Lux</p>`:'';const dli=p.careNotes.minDLI!=null||p.careNotes.maxDLI!=null?`<p><strong>DLI:</strong> ${esc(p.careNotes.minDLI??'–')}–${esc(p.careNotes.maxDLI??'–')} mol/m²/Tag</p>`:'';content+=section('Pflanzenwissen',card(notes+light+dli))}
  content+=section('Jahresüberblick',card(annualChart(p)+'<div class="small">Blau: geschätzte Gießprüfungen · Grün: Düngen pro Monat</div>'));
  if(p.milestoneDate)content+=section('Geburtstag',card(formatDate(p.milestoneDate)));
  if(p.sensor){const actions=button('Aktualisieren','sensor-refresh',p.id,'tiny secondary')+button('Bearbeiten','sensor-form',p.id,'tiny secondary');content+=section('Bodenfeuchtesensor',card(`<strong>${esc(p.sensor.entity)}</strong><div id="sensor-reading" class="small">Messwert laden …</div><div class="actions">${actions}</div>`))}
  else content+=section('Bodenfeuchtesensor',card(button('Sensor verbinden','sensor-form',p.id)));
  const latestMarkup=latest?`<div class="row">${latest.photoName?`<img class="plantthumb" src="${attr(photo(latest.photoName))}" alt="Fortschritt">`:''}<div class="grow"><strong>${formatDate(latest.date)}</strong><div class="small">${latest.heightCM!=null?`${esc(latest.heightCM)} cm · `:''}${esc(short(latest.note))}</div></div></div>`:'Noch kein Eintrag';
  content+=section('Fortschritt',card(latestMarkup+`<div class="actions">${button('Fortschritt festhalten','progress-form',p.id)}${button('Verlauf ansehen','history',p.id,'secondary')}</div>`));
  return content;
}
function annualChart(p){const pts=(kind)=>Array.from({length:12},(_,i)=>{const winter=[0,1,2,10,11].includes(i);const base=kind==='water'?Math.round(30/(interval({...p,nearHeater:winter&&p.nearHeater},`${new Date().getFullYear()}-${String(i+1).padStart(2,'0')}-15`))):((p.taskPlans||[]).find(x=>x.task==='Düngen')?Math.max(0.2,30/(((p.taskPlans||[]).find(x=>x.task==='Düngen').days||28)*(winter?2:1))):0);return `${20+i*27},${135-Math.min(110,base*(kind==='water'?13:55))}`}).join(' ');return `<svg class="chart" viewBox="0 0 340 160" role="img" aria-label="Geschätzte Prüfungen und Düngungen über zwölf Monate"><path class="water" d="M${pts('water').replaceAll(' ',' L')}"/><path class="fertilize" d="M${pts('fertilize').replaceAll(' ',' L')}"/></svg>`}
function settingsPage(){return title('Dein Bereich','Einstellungen')+section('Verbindungen',card(`<div class="settingrow"><div class="grow"><strong>Pflanzendienste</strong><div class="small">Suche, Erkennung und Pflegehinweise</div></div>${button('Ansehen','services','','tiny secondary')}</div><div class="settingrow"><div class="grow"><strong>Smart Home</strong><div class="small">Sensoren und weitere Dienste</div></div>${button('Ansehen','smart-home','','tiny secondary')}</div>`))+section('App',card(`<div class="settingrow"><div class="grow"><strong>Darstellung</strong></div>${button('Einstellen','appearance','','tiny secondary')}</div>`))+section('Deine Daten',card(`<div class="settingrow"><div class="grow">Sicherung herunterladen</div>${button('Export','export','','tiny secondary')}</div><div class="settingrow"><div class="grow">Sicherung einlesen</div><label class="btn tiny secondary">Datei wählen<input id="import-file" type="file" accept="application/json" hidden></label></div><div class="settingrow"><div class="grow">Konto</div>${button('Ansehen','account','','tiny secondary')}</div>`))}
function openSheet(heading,body,footer='',nested=false){if(nested&&sheetRoot.firstElementChild)app.sheetStack.push(sheetRoot.firstElementChild);else if(!nested)app.sheetStack=[];sheetRoot.innerHTML=`<div class="sheetback" data-action="close-sheet"><div class="sheet" role="dialog" aria-modal="true" aria-label="${attr(heading)}"><header><h2>${heading}</h2><button class="btn icon secondary" data-action="close-sheet" aria-label="Schließen">×</button></header><main>${body}</main>${footer?`<footer>${footer}</footer>`:''}</div></div>`}
function closeSheet(force=false){if(!force&&app.sheetStack.length)sheetRoot.replaceChildren(app.sheetStack.pop());else{app.sheetStack=[];sheetRoot.innerHTML=''}}
function roomForm(id){const r=id?structuredClone(room(id)):{id:uid(),name:'',windows:[]};if(!r)return;openSheet('Raum',`<form id="room-form" data-id="${attr(r.id)}">${field('Name','<input name="name" value="'+attr(r.name)+'" required>')}<h3>Fenster</h3><p class="small">Du kannst mehrere Fenster mit ihrer Ausrichtung hinterlegen.</p><div id="room-windows">${(r.windows||[]).map((w,i)=>windowRow(w,i)).join('')}</div><div class="actions"><button class="btn secondary" type="button" data-action="add-window">+ Fenster</button></div></form>`,`<button class="btn" type="submit" form="room-form">Speichern</button>${id?button('Löschen','delete-room',id,'danger'):''}`)}
function windowRow(w,i){return `<div class="card" data-window><div class="row">${field('Fenstername',`<input name="windowName" value="${attr(w.name)}" placeholder="Fenster ${i+1}">`)}${field('Ausrichtung',`<select name="windowDirection"><option value="">Unbekannt</option>${select(directions,w.direction)}</select>`)}<button class="btn icon ghost" type="button" data-action="remove-window" aria-label="Fenster entfernen">×</button></div><input type="hidden" name="windowID" value="${attr(w.id)}"></div>`}
function plantForm(id){
  const p=id&&typeof id==='object'?structuredClone(id):id?structuredClone(byId(id)):newPlant();
  if(!p)return;
  const existing=!!byId(p.id),r=room(p.roomID),src=imageFor(p);
  const step=(n,content)=>'<section data-wizard-step="'+n+'" '+(existing||n===0?'':'hidden')+'>'+content+'</section>';
  const roomOptions=app.rooms.map(x=>'<option value="'+attr(x.id)+'" '+(x.id===p.roomID?'selected':'')+'>'+esc(x.name)+'</option>').join('');
  const windowOptions=(r?.windows||[]).map(x=>'<option value="'+attr(x.id)+'" '+(x.id===p.windowID?'selected':'')+'>'+esc(x.name)+'</option>').join('');
  const basic='<div class="banner">Pflanzenart eingeben oder mit einem Foto erkennen.</div>'
    +'<div class="actions">'+button('Pflanzenbibliothek suchen','library','','secondary')+button('Foto erkennen','identify','','secondary')+'</div>'
    +'<div class="formgrid">'+field('Pflanzenart','<input name="species" value="'+attr(p.species)+'" required autocomplete="off" placeholder="z. B. Alocasia zebrina"><div id="species-suggestions" class="suggestions" hidden></div>')
    +field('Spitzname','<input name="nickname" value="'+attr(p.nickname)+'" placeholder="optional">')+'</div>'
    +'<input type="hidden" name="scientificName" value="'+attr(p.scientificName)+'">'
    +field('Foto',(src?'<img class="preview" src="'+attr(src)+'" alt="Aktuelles Pflanzenfoto">':'')+'<input type="file" name="photo" accept="image/*"><span class="small">Optional: Foto auswählen und erkennen lassen.</span>')
    +'<input type="hidden" name="photoName" value="'+attr(p.photoName)+'"><input type="hidden" name="referenceImageURL" value="'+attr(p.referenceImageURL)+'"><input type="hidden" name="useReferenceImage" value="'+(p.useReferenceImage?'1':'0')+'"><input type="hidden" name="careNotes" value="'+attr(JSON.stringify(p.careNotes))+'">'
    +'<h3>Standort & Licht</h3><div class="formgrid">'
    +field('Raum','<select name="roomID"><option value=""></option>'+roomOptions+'</select>')
    +field('Fenster','<select name="windowID"><option value=""></option>'+windowOptions+'</select>')+'</div><div class="formgrid">'
    +field('Fensterausrichtung <button class="info" type="button" data-action="info" data-id="window" aria-label="Info zur Fensterausrichtung">?</button>','<select name="windowDirection"><option value=""></option>'+select(directions,p.windowDirection)+'</select>')
    +field('Abstand zum Fenster (cm)','<input type="number" name="windowDistanceCM" min="0" step="1" value="'+attr(p.windowDistance==null?'':Math.round(p.windowDistance*100))+'">')+'</div>'
    +'<div class="row between"><label for="growLight">Wachstumslicht <button class="info" type="button" data-action="info" data-id="light" aria-label="Info zum Wachstumslicht">?</button></label><input type="checkbox" id="growLight" name="growLight" '+(p.growLight?'checked':'')+'></div>'
    +'<div id="grow-light-fields" '+(p.growLight?'':'hidden')+'><div class="formgrid">'
    +field('Stunden pro Tag','<input name="lightHours" type="number" min="0" max="24" step="0.5" value="'+attr(p.lightHours)+'">')
    +field('PPFD (µmol/m²/s)','<input name="ppfd" type="number" min="0" step="1" value="'+attr(p.ppfd)+'">')+'</div>'
    +'<div class="small">DLI: <span id="dli-value">'+(p.dli!=null?esc(Number(p.dli).toFixed(1)):'–')+'</span> mol/m²/Tag</div></div>'
    +'<div class="row between"><label for="nearHeater">In Heizungsnähe</label><input type="checkbox" id="nearHeater" name="nearHeater" '+(p.nearHeater?'checked':'')+'></div>';
  const pot='<h3>Wie groß ist der Topf?</h3><p class="small">Durchmesser in Zentimetern</p>'
    +field('Topfdurchmesser','<div class="inlineinput"><input type="number" name="potDiameter" min="2" max="80" step="0.5" value="'+attr(p.potDiameter)+'"> cm</div><input type="range" name="potRange" min="2" max="80" step="0.5" value="'+attr(p.potDiameter)+'">');
  const substrate='<h3>Welches Substrat nutzt du?</h3>'
    +field('Substrat','<button type="button" class="btn secondary" data-action="substrate">'+esc(substrateName(p.substrate))+'</button><input type="hidden" name="substrate" value="'+attr(substrateName(p.substrate))+'">');
  const presets=[['','Nicht bekannt'],['0','Heute'],['1','Gestern'],['2','Vorgestern'],['3','Vor 3 Tagen'],['7','Vor einer Woche'],['14','Vor 2 Wochen'],['custom','Anderes Datum']];
  const last='<h3>Wann wurde zuletzt gegossen?</h3>'
    +field('Zeitraum','<select name="wateredPreset">'+presets.map(([value,label])=>'<option value="'+value+'" '+(value===(p.lastWatered?'custom':'')?'selected':'')+'>'+label+'</option>').join('')+'</select>')
    +field('Genaues Datum','<input type="date" name="lastWatered" value="'+attr(dateOnly(p.lastWatered))+'" '+(existing&&p.lastWatered?'':'hidden')+'>');
  const height='<h3>Wie hoch ist die Pflanze?</h3><p class="small">Optional. Die Höhe beeinflusst den ersten Prüftermin leicht.</p>'
    +field('Pflanzenhöhe (cm)','<input type="number" name="heightCM" min="0" max="1000" step="0.1" value="'+attr(p.heightCM)+'">');
  const birthday=existing?field('Geburtstag','<input type="date" name="milestoneDate" value="'+attr(dateOnly(p.milestoneDate))+'">'):'';
  const body='<form id="plant-form" data-id="'+attr(p.id)+'">'
    +step(0,basic)+step(1,pot)+step(2,substrate)+step(3,last)+step(4,height)+birthday+'</form>';
  const footer=existing?'<button class="btn" type="submit" form="plant-form">Speichern</button>'+button('Löschen','delete-plant',p.id,'danger')
    :'<button class="btn" type="button" data-action="plant-next">Weiter</button><button class="btn secondary" type="button" data-action="plant-prev" hidden>Zurück</button><button class="btn" type="submit" form="plant-form" hidden>Pflanze anlegen</button>';
  openSheet(existing?'Pflanze bearbeiten':'Pflanze anlegen',body,footer);
  sheetRoot.dataset.plant=JSON.stringify(p);
  sheetRoot.dataset.plantStep='0';
}
function updateRoomWindowChoices(){const form=document.querySelector('#plant-form');if(!form)return;const r=room(form.elements.roomID.value),sel=form.elements.windowID;sel.innerHTML='<option value=""></option>'+(r?.windows||[]).map(w=>`<option value="${attr(w.id)}">${esc(w.name)}</option>`).join('');const w=r?.windows?.[0];sel.value=w?.id||'';form.elements.windowDirection.value=w?.direction||''}
function valuesPlant(form){
  const initial=JSON.parse(sheetRoot.dataset.plant),x=form.elements;
  const num=n=>x[n].value===''?null:Number(x[n].value);
  const distance=num('windowDistanceCM');
  const editing=!!byId(initial.id);
  const p={...initial,
    species:x.species.value.trim(),nickname:x.nickname.value.trim(),
    scientificName:x.scientificName.value.trim()||null,
    roomID:x.roomID.value||null,windowID:x.windowID.value||null,
    windowDirection:x.windowDirection.value||null,
    windowDistance:distance===null?null:distance/100,
    growLight:x.growLight.checked,lightHours:num('lightHours'),ppfd:num('ppfd'),
    nearHeater:x.nearHeater.checked,potDiameter:num('potDiameter')||12,
    heightCM:num('heightCM'),substrate:x.substrate.value,
    lastWatered:x.lastWatered.value||null,
    milestoneDate:editing?(x.milestoneDate.value||null):today(),
    photoName:x.photoName.value||null,
    referenceImageURL:x.referenceImageURL.value||null,
    useReferenceImage:x.useReferenceImage.value==='1',
    careNotes:JSON.parse(x.careNotes.value||'null')
  };
  p.dli=p.growLight&&p.lightHours!=null&&p.ppfd!=null?Math.round(p.lightHours*p.ppfd*0.0036*10)/10:null;
  if(!editing){
    p.nextCheck=addDays(dateOnly(p.lastWatered)||today(),interval(p));
    p.taskPlans=starterPlans(p.species);
    if(p.heightCM!=null)(p.events||=[]).push(event('Fortschritt',{heightCM:p.heightCM,note:'Startgröße'}));
  }
  return p;
}
function setPlantStep(step){const form=document.querySelector('#plant-form');if(!form)return;const next=Math.max(0,Math.min(4,step));if(next>0&&!form.elements.species.value.trim()){form.elements.species.focus();toast('Bitte zuerst eine Pflanzenart eingeben.');return}sheetRoot.dataset.plantStep=String(next);form.querySelectorAll('[data-wizard-step]').forEach(section=>section.hidden=Number(section.dataset.wizardStep)!==next);const footer=sheetRoot.querySelector('.sheet footer');footer.querySelector('[data-action="plant-next"]').hidden=next===4;footer.querySelector('[data-action="plant-prev"]').hidden=next===0;footer.querySelector('[type="submit"]').hidden=next!==4;sheetRoot.querySelector('.sheet main').scrollTop=0}
async function upload(file){if(!file)return null;if(file.size>8*1024*1024)throw Error('Das Foto darf höchstens 8 MB groß sein.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Bitte ein JPG-, PNG- oder WebP-Bild wählen.');return (await api('/api/photos','POST',file,file.type)).id}
function library(){const form=document.querySelector('#plant-form');if(!form)return;const term=form.elements.species.value.trim();openSheet('Pflanzenbibliothek',`<div class="field"><label>Art oder Name</label><div class="row"><input id="library-query" value="${attr(term)}" placeholder="Pflanze suchen"><button class="btn" data-action="library-search">Suchen</button></div></div><div id="library-results" class="small">Suche nach einer Pflanzenart.</div>`,button('Zurück zum Formular','restore-plant','','secondary'),true);if(term.length>=2)librarySearch()}
async function librarySearch(){const q=document.querySelector('#library-query')?.value.trim();if(!q)return;const target=document.querySelector('#library-results');target.textContent='Suche läuft …';try{const result=await api('/api/services/search?q='+encodeURIComponent(q));target.innerHTML=result.length?result.map(item=>`<div class="plantrow"><div class="grow"><strong>${esc(item.title)}</strong><div class="small">${esc(item.scientificName)}</div></div><button class="btn tiny secondary" data-action="choose-library" data-name="${attr(item.title)}" data-scientific="${attr(item.scientificName)}" data-image="${attr(item.imageURL||'')}">Übernehmen</button></div>`).join(''):empty('Keine Treffer gefunden.')}catch(e){target.textContent=e.message}}
function identify(){const form=document.querySelector('#plant-form');if(!form)return;const file=form.elements.photo.files?.[0];if(!file){toast('Wähle zuerst ein Pflanzenfoto.');return}openSheet('Foto erkennen',`<p class="small">Das ausgewählte Foto wird an Pl@ntNet gesendet.</p><div id="identify-results">Erkennung läuft …</div>`,button('Zurück zum Formular','restore-plant','','secondary'),true);file.arrayBuffer().then(b=>api('/api/services/identify','POST',b,file.type||'image/jpeg')).then(result=>{const target=document.querySelector('#identify-results');if(target)target.innerHTML=result.length?result.map(x=>`<div class="plantrow"><div class="grow"><strong>${esc(x.commonName||x.scientificName)}</strong><div class="small">${esc(x.scientificName)} · ${Math.round(x.score*100)} %</div></div><button class="btn tiny secondary" data-action="choose-identification" data-name="${attr(x.commonName||x.scientificName)}" data-scientific="${attr(x.scientificName)}">Übernehmen</button></div>`).join(''):empty('Keine passende Art erkannt.')}).catch(e=>{const target=document.querySelector('#identify-results');if(target)target.textContent=e.message})}
function restorePlant(){closeSheet()}
async function chooseSpecies(target){if(app.sheetStack.length)closeSheet();const form=document.querySelector('#plant-form');if(!form)return;const scientific=target.dataset.scientific||target.dataset.name;form.elements.species.value=target.dataset.name;form.elements.scientificName.value=scientific;form.elements.referenceImageURL.value=target.dataset.image||'';form.elements.useReferenceImage.value=target.dataset.image?'1':'0';const suggestions=document.querySelector('#species-suggestions');if(suggestions)suggestions.hidden=true;if(app.services.plantbook&&scientific){try{const advice=await api('/api/services/advice?name='+encodeURIComponent(scientific));form.elements.careNotes.value=JSON.stringify(advice)}catch(e){toast('Pflegehinweise: '+e.message)}}}
let suggestionTimer=0,suggestionSequence=0;
function suggestSpecies(value){clearTimeout(suggestionTimer);const box=document.querySelector('#species-suggestions'),query=value.trim();if(!box)return;if(!app.services.trefle||query.length<2){box.hidden=true;box.innerHTML='';return}const sequence=++suggestionSequence;suggestionTimer=setTimeout(async()=>{try{const result=await api('/api/services/search?q='+encodeURIComponent(query));if(sequence!==suggestionSequence||document.querySelector('#species-suggestions')!==box)return;box.innerHTML=result.map(item=>`<button class="suggestion" type="button" data-action="choose-suggestion" data-name="${attr(item.title)}" data-scientific="${attr(item.scientificName)}" data-image="${attr(item.imageURL||'')}"><strong>${esc(item.title)}</strong><span>${esc(item.scientificName)}</span></button>`).join('');box.hidden=!result.length}catch{box.hidden=true}},300)}
function postpone(id){openSheet(byId(id)?.substrate==='Wasser'?'Wasserprüfung zurückstellen':'Erde zurückstellen',`<p class="lead">Wann möchtest du die Erde erneut prüfen?</p><div class="actions">${[1,2,3].map(n=>button(n===1?'Morgen prüfen':`In ${n} Tagen prüfen`,'postpone-days',id,'secondary').replace('data-id=',`data-days="${n}" data-id=`)).join('')}</div>`)}
function wetQuestion(id,days){const waterPlant=byId(id)?.substrate==='Wasser';openSheet(waterPlant?'War noch genug Wasser vorhanden?':'War die Erde noch feucht?',`<p class="lead">Die Beobachtung hilft, den Pflegeplan einzuschätzen.</p>`,`${button(waterPlant?'Ja, Wasserstand okay':'Ja, noch feucht','postpone-save',id,'').replace('data-id=',`data-days="${days}" data-wet="1" data-id=`)}${button('Nein','postpone-save',id,'secondary').replace('data-id=',`data-days="${days}" data-wet="0" data-id=`)}`)}
function wateringChoice(id){openSheet('Gegossen',`<p class="lead">War die Erde bereits trocken? Nur dann lernt der Pflegeplan aus dieser früheren Gießung.</p>`,`${button('Ja, trocken','water-save',id,'').replace('data-id=',`data-dry="1" data-id=`)}${button('Vorsorglich gegossen','water-save',id,'secondary').replace('data-id=',`data-dry="0" data-id=`)}`)}
function carePlan(id){const p=byId(id);openSheet('Pflegeplan',`<form id="plan-form" data-id="${attr(id)}"><p class="small">Leere Felder schalten eine Aufgabe aus. Winterliches Düngen wird automatisch seltener geplant.</p>${tasks.map(task=>field(task,`<div class="inlineinput"><input type="number" min="1" max="730" name="${attr(task)}" value="${attr((p.taskPlans||[]).find(x=>x.task===task)?.days||'')}" placeholder="Aus"> Tage</div>`)).join('')}</form>`,`<button class="btn" type="submit" form="plan-form">Pflegeplan speichern</button>`)}
function progressForm(id){const p=byId(id),height=[...(p.events||[])].reverse().find(e=>e.heightCM!=null)?.heightCM??p.heightCM;openSheet('Fortschritt festhalten',`<form id="progress-form" data-id="${attr(id)}">${field('Foto','<input type="file" name="photo" accept="image/*">')}${field('Größe (cm)',`<input type="number" name="height" min="0" max="1000" step="0.1" value="${attr(height)}">`)}${field('Notiz','<textarea name="note" placeholder="Was hat sich verändert?"></textarea>')}<div class="row between"><label for="newLeaf">Neues Blatt</label><input id="newLeaf" name="newLeaf" type="checkbox"></div></form>`,`<button class="btn" type="submit" form="progress-form">Fortschritt speichern</button>`)}
function history(id){const p=byId(id),events=[...(p.events||[])].sort((a,b)=>b.date.localeCompare(a.date)),progress=events.filter(e=>e.kind==='Fortschritt'),other=events.filter(e=>e.kind!=='Fortschritt');const list=values=>values.length?values.map(e=>card(`<div class="row">${e.photoName?`<img class="plantthumb" src="${attr(photo(e.photoName))}" alt="">`:''}<div><strong>${esc(e.kind)}</strong><div class="small">${formatDate(e.date)}${e.heightCM!=null?` · ${esc(e.heightCM)} cm`:''}</div>${e.note?`<p>${esc(e.note)}</p>`:''}</div></div>`)).join(''):empty('Noch keine Einträge.');openSheet('Verlauf · '+display(p),`<h3>Fortschritt</h3>${list(progress)}<h3>Pflege</h3>${list(other)}`)}
function sensorForm(id){const s=byId(id).sensor||{};openSheet('Bodenfeuchtesensor',`<form id="sensor-form" data-id="${attr(id)}">${field('Home-Assistant-Entität',`<input name="entity" value="${attr(s.entity)}" placeholder="sensor.pflanze_bodenfeuchte">`)}${field('Trocken ab Messwert',`<input type="number" name="threshold" step="0.1" value="${attr(s.dryThreshold)}">`)}<div class="row between"><label for="lowerDrier">Kleinerer Wert bedeutet trockener</label><input id="lowerDrier" type="checkbox" name="lowerDrier" ${s.lowerIsDrier!==false?'checked':''}></div></form>`,`<button class="btn" type="submit" form="sensor-form">Speichern</button>`)}
async function sensorRefresh(id){const p=byId(id);if(!p?.sensor)return;const target=document.querySelector('#sensor-reading');if(target)target.textContent='Messwert laden …';try{const readings=await api('/api/homeassistant/readings?entity='+encodeURIComponent(p.sensor.entity));const value=readings[p.sensor.entity]?.value;const dry=p.sensor.dryThreshold!=null?(p.sensor.lowerIsDrier!==false?value<=p.sensor.dryThreshold:value>=p.sensor.dryThreshold):null;if(target)target.textContent=value==null?'Kein gültiger Messwert':`${value}${dry===null?'':dry?' · Eher trocken':' · Noch feucht'}`}catch(e){if(target)target.textContent=e.message}}
const serviceLink=(url,label)=>`<a href="${attr(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
const credentialForm=(key,heading,description,connected,fields,url)=>card(`<div class="row between"><div><h3>${heading}</h3><div class="small">${description}</div></div><span class="pill">${connected?'Verbunden':'Nicht eingerichtet'}</span></div><p class="small">${serviceLink(url,'Zugang erhalten')}</p><form class="credential-form" data-service="${key}">${connected?`<div class="actions">${button('Verbindung entfernen','delete-credential',key,'danger')}</div>`:fields.map(([name,label,type])=>field(label,`<input name="${name}" type="${type}" autocomplete="off" required>`)).join('')+'<div class="actions"><button class="btn" type="submit">Zugang speichern</button></div>'}</form>`);
async function services(){openSheet('Pflanzendienste','<div id="service-status">Verbindungen laden …</div>');try{app.services=await api('/api/services/status');const t=document.querySelector('#service-status');if(t)t.innerHTML='<p class="small">Zugangsdaten gelten nur für dein Konto. Andere Konten richten ihre eigenen Verbindungen ein.</p>'+credentialForm('trefle','Trefle','Pflanzenbibliothek',app.services.trefle,[['token','API-Schlüssel','password']],'https://trefle.io/')+credentialForm('plantbook','Open Plantbook','Pflegehinweise',app.services.plantbook,[['clientId','Client-ID','text'],['clientSecret','Client-Secret','password']],'https://open.plantbook.io/')+credentialForm('plantnet','Pl@ntNet','Fotoerkennung',app.services.plantnet,[['token','API-Schlüssel','password']],'https://my.plantnet.org/')}catch(e){const t=document.querySelector('#service-status');if(t)t.textContent=e.message}}
async function smartHome(){openSheet('Smart Home','<div id="home-status">Verbindung laden …</div>');try{const s=await api('/api/homeassistant/status');const t=document.querySelector('#home-status');if(t)t.innerHTML='<p class="small">Verbinde Smart-Home-Dienste für Sensorwerte. Jede Verbindung gilt nur für dein Konto.</p>'+credentialForm('homeassistant','Home Assistant','Bodenfeuchtesensoren',s.connected,[['url','Adresse, zum Beispiel http://192.168.1.10:8123','url'],['token','Langlebiger Zugriffstoken','password']],'https://www.home-assistant.io/docs/authentication/')}catch(e){const t=document.querySelector('#home-status');if(t)t.textContent=e.message}}
function account(){openSheet('Konto',`${card(`<form id="account-form">${field('Benutzername',`<input name="username" value="${attr(app.auth?.username||'')}" required>`)}<button class="btn" type="submit">Benutzername speichern</button></form>`)}${card(`<h3>Passwort ändern</h3><form id="password-form">${field('Bisheriges Passwort','<input type="password" name="currentPassword" autocomplete="current-password" required>')}${field('Neues Passwort','<input type="password" name="newPassword" autocomplete="new-password" minlength="10" required>')}<button class="btn" type="submit">Passwort ändern</button></form>`)}<div class="actions">${button('Abmelden','logout','','secondary')}</div>`)}
function appearance(){const mode=app.preferences.appearance||'system';openSheet('Darstellung',`<div class="seg">${[['system','System'],['light','Hell'],['dark','Dunkel']].map(([id,label])=>`<button data-action="set-theme" data-id="${id}" class="${mode===id?'active':''}">${label}</button>`).join('')}</div>`)}
async function setPreference(change){app.preferences={...app.preferences,...change};await api('/api/preferences','PUT',app.preferences);applyTheme();render()}
function info(kind){const text={window:'Die Ausrichtung beeinflusst das natürliche Licht. Südliche Fenster bekommen meist mehr direktes Licht, nördliche eher gleichmäßiges, schwächeres Licht.',light:'PPFD ist die Lichtstärke pro Sekunde. Aus PPFD und Stunden berechnet die App den Tageswert DLI.'}[kind]||'';openSheet('Info',`<p>${esc(text)}</p>`,'',!!document.querySelector('#plant-form'))}

document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,id=target.dataset.id;if(action==='close-sheet'&&target.classList.contains('sheetback')&&e.target!==target)return;try{
  if(action==='tab'){app.tab=id;app.detail=null;app.sticky=false;closeSheet(true);render();scrollTo(0,0)}
  else if(action==='detail'){app.tab='plants';app.detail=id;app.sticky=false;render();scrollTo(0,0);if(byId(id)?.sensor)sensorRefresh(id)}
  else if(action==='back'){app.detail=null;app.sticky=false;render();scrollTo(0,0)}
  else if(action==='close-sheet')closeSheet();
  else if(action==='clear-toast'){clearTimeout(app.toastTimer);toastRoot.innerHTML='';app.undo=null}
  else if(action==='undo'&&app.undo){const previous=app.undo;app.undo=null;await savePlant(previous,'Rückgängig gemacht')}
  else if(action==='plant-form'){app.formDraft=null;app.formPhoto=null;plantForm(id||null)}
  else if(action==='plant-next')setPlantStep(Number(sheetRoot.dataset.plantStep||0)+1);
  else if(action==='plant-prev')setPlantStep(Number(sheetRoot.dataset.plantStep||0)-1);
  else if(action==='room-form')roomForm(id||null);
  else if(action==='add-window')document.querySelector('#room-windows')?.insertAdjacentHTML('beforeend',windowRow({id:uid(),name:'',direction:''},document.querySelectorAll('[data-window]').length));
  else if(action==='remove-window')target.closest('[data-window]')?.remove();
  else if(action==='postpone')postpone(id);
  else if(action==='postpone-days')wetQuestion(id,+target.dataset.days);
  else if(action==='postpone-save'){await mutate(id,p=>postponeCheck(p,+target.dataset.days,target.dataset.wet==='1'),'Prüfung zurückgestellt');closeSheet()}
  else if(action==='water'){await mutate(id,p=>water(p,true),'Gegossen');closeSheet()}
  else if(action==='watering-choice')wateringChoice(id);
  else if(action==='water-save'){await mutate(id,p=>water(p,target.dataset.dry==='1'),'Gegossen');closeSheet()}
  else if(action==='finish-task'){const task=target.dataset.task;if(task==='Fortschritt festhalten')progressForm(id);else await mutate(id,p=>finishTask(p,task),`${task} erledigt`)}
  else if(action==='care-plan')carePlan(id);
  else if(action==='progress-form')progressForm(id);
  else if(action==='history')history(id);
  else if(action==='sensor-form')sensorForm(id);
  else if(action==='sensor-refresh')sensorRefresh(id);
  else if(action==='services')services();
  else if(action==='smart-home')smartHome();
  else if(action==='account')account();
  else if(action==='delete-credential'){if(confirm('Verbindung für dein Konto entfernen?')){await api('/api/services/credentials/'+encodeURIComponent(id),'DELETE');if(id==='homeassistant')await smartHome();else await services();toast('Verbindung entfernt')}}
  else if(action==='appearance')appearance();
  else if(action==='set-theme'){await setPreference({appearance:id});appearance()}
  else if(action==='info')info(id);
  else if(action==='substrate'){const form=document.querySelector('#plant-form');if(!form)return;const current=form.elements.substrate.value;openSheet('Substrat',substrates.map(x=>`<div class="settingrow"><div class="grow">${esc(x)}</div>${button(current===x?'Ausgewählt':'Wählen','choose-substrate',x,'tiny secondary')}</div>`).join(''),'',true)}
  else if(action==='choose-substrate'){closeSheet();const form=document.querySelector('#plant-form');if(form){form.elements.substrate.value=id;form.querySelector('[data-action=substrate]').textContent=id}}
  else if(action==='library')library();
  else if(action==='library-search')librarySearch();
  else if(action==='choose-library'||action==='choose-identification'||action==='choose-suggestion')chooseSpecies(target);
  else if(action==='identify')identify();
  else if(action==='restore-plant')restorePlant();
  else if(action==='delete-plant'){if(confirm('Diese Pflanze samt Verlauf wirklich löschen?')){await api('/api/plants/'+encodeURIComponent(id),'DELETE');app.plants=app.plants.filter(p=>p.id!==id);app.detail=null;closeSheet();render();toast('Pflanze gelöscht')}}
  else if(action==='delete-room'){if(confirm('Raum löschen? Seine Pflanzen bleiben erhalten.')){await api('/api/rooms/'+encodeURIComponent(id),'DELETE');app.rooms=app.rooms.filter(r=>r.id!==id);for(const p of app.plants.filter(x=>x.roomID===id)){p.roomID=null;p.windowID=null;await savePlant(p,'')}closeSheet();render();toast('Raum gelöscht')}}
  else if(action==='export'){const data=await api('/api/export');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='pflanzenpflege-sicherung.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
  else if(action==='logout'){await api('/api/auth/logout','POST',{});app.auth=await api('/api/auth/status');app.auth.firstAccountServer=app.auth.firstAccount;app.plants=[];app.rooms=[];closeSheet();render()}
  else if(action==='reload')location.reload();
  else if(action==='register-form'){app.auth.firstAccount=true;renderAuth();if(!app.auth.registrationOpen)toast('Neue Konten sind nicht freigegeben.')}
  else if(action==='login-form'){app.auth.firstAccount=false;renderAuth()}
}catch(error){toast(error.message||'Etwas hat nicht funktioniert.')}});

document.addEventListener('submit',async e=>{const form=e.target;if(!['auth-form','room-form','plant-form','plan-form','progress-form','sensor-form','account-form','password-form'].includes(form.id)&&!form.classList.contains('credential-form'))return;e.preventDefault();const submit=form.querySelector('[type=submit]')||document.querySelector(`[form="${form.id}"]`);if(submit)submit.disabled=true;try{
  if(form.id==='auth-form'){const mode=form.dataset.mode;await api('/api/auth/'+mode,'POST',{username:form.elements.username.value,password:form.elements.password.value,invite:form.elements.invite?.value||''});app.auth=await api('/api/auth/status');await load()}
  if(form.id==='account-form'){const result=await api('/api/account','PUT',{username:form.elements.username.value.trim()});app.auth.username=result.username;closeSheet();toast('Benutzername gespeichert')}
  if(form.id==='password-form'){await api('/api/account/password','PUT',{currentPassword:form.elements.currentPassword.value,newPassword:form.elements.newPassword.value});closeSheet();toast('Passwort geändert')}
  if(form.classList.contains('credential-form')){const service=form.dataset.service;const values=Object.fromEntries([...form.elements].filter(x=>x.name).map(x=>[x.name,x.value]));await api('/api/services/credentials/'+encodeURIComponent(service),'PUT',values);if(service==='homeassistant')await smartHome();else await services();toast('Verbindung gespeichert')}
  if(form.id==='room-form'){const r={id:form.dataset.id,name:form.elements.name.value.trim(),windows:[...form.querySelectorAll('[data-window]')].map(row=>({id:row.querySelector('[name=windowID]').value,name:row.querySelector('[name=windowName]').value.trim()||'Fenster',direction:row.querySelector('[name=windowDirection]').value||null}))};if(!r.name)throw Error('Bitte einen Raumnamen eingeben.');await saveRoom(r);closeSheet()}
  if(form.id==='plant-form'){const p=valuesPlant(form);if(!p.species)throw Error('Bitte eine Pflanzenart eingeben.');const file=form.elements.photo.files?.[0]||app.formPhoto;if(file)p.photoName=await upload(file);await savePlant(p,'Pflanze gespeichert');app.formPhoto=null;app.formDraft=null;closeSheet()}
  if(form.id==='plan-form'){const id=form.dataset.id;await mutate(id,p=>{p.taskPlans=tasks.flatMap(task=>{const n=Number(form.elements.namedItem(task).value),old=(p.taskPlans||[]).find(x=>x.task===task);return n>=1&&n<=730?[{task,days:n,next:old&&old.days===n?old.next:addDays(today(),n)}]:[]})},'Pflegeplan gespeichert');closeSheet()}
  if(form.id==='progress-form'){const file=form.elements.photo.files?.[0],image=file?await upload(file):null;await mutate(form.dataset.id,p=>{const height=form.elements.height.value?Number(form.elements.height.value):null;const note=form.elements.note.value.trim()+(form.elements.newLeaf.checked?' · Neues Blatt':'');(p.events||=[]).push(event('Fortschritt',{note,photoName:image,heightCM:height}));if(height!=null)p.heightCM=height;if(image)p.photoName=image;const plan=(p.taskPlans||[]).find(x=>x.task==='Fortschritt festhalten');if(plan)plan.next=addDays(today(),plan.days)},'Fortschritt gespeichert');closeSheet()}
  if(form.id==='sensor-form'){const entity=form.elements.entity.value.trim();if(entity&&!/^sensor\.[a-z0-9_]+$/.test(entity))throw Error('Die Sensor-ID muss mit sensor. beginnen.');await mutate(form.dataset.id,p=>{p.sensor=entity?{entity,dryThreshold:form.elements.threshold.value===''?null:Number(form.elements.threshold.value),lowerIsDrier:form.elements.lowerDrier.checked}:null},'Sensor gespeichert');closeSheet()}
}catch(error){toast(error.message||'Speichern fehlgeschlagen.')}finally{if(submit)submit.disabled=false}});

document.addEventListener('input',e=>{const f=e.target.closest('#plant-form');if(!f)return;if(e.target.name==='species'){f.elements.scientificName.value='';f.elements.careNotes.value='null';f.elements.referenceImageURL.value='';f.elements.useReferenceImage.value='0';suggestSpecies(e.target.value)}if(e.target.name==='potRange')f.elements.potDiameter.value=e.target.value;if(e.target.name==='potDiameter')f.elements.potRange.value=e.target.value;if(['lightHours','ppfd'].includes(e.target.name)){const h=Number(f.elements.lightHours.value),ppfd=Number(f.elements.ppfd.value);f.querySelector('#dli-value').textContent=h&&ppfd?(h*ppfd*.0036).toFixed(1):'–'}});
document.addEventListener('change',async e=>{const form=e.target.closest('#plant-form');if(form&&e.target.name==='roomID')updateRoomWindowChoices();if(form&&e.target.name==='windowID'){const w=room(form.elements.roomID.value)?.windows?.find(x=>x.id===e.target.value);form.elements.windowDirection.value=w?.direction||''}if(form&&e.target.name==='growLight')form.querySelector('#grow-light-fields').hidden=!e.target.checked;if(form&&e.target.name==='wateredPreset'){const date=form.elements.lastWatered;date.hidden=e.target.value!=='custom';date.value=e.target.value==='custom'?(date.value||today()):e.target.value===''?'':addDays(today(),-Number(e.target.value))}if(e.target.id==='import-file'){const file=e.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!confirm(`Sicherung mit ${data.plants?.length||0} Pflanzen einlesen?`))return;await api('/api/import','POST',data);await load();toast('Sicherung eingelesen')}catch(error){toast(error.message)}}});

async function start(){root.innerHTML='<div class="loading">Pflanzenpflege lädt …</div>';try{app.auth=await api('/api/auth/status');app.auth.firstAccountServer=app.auth.firstAccount;if(app.auth.authenticated)await load();else renderAuth();if('serviceWorker' in navigator&&window.isSecureContext)navigator.serviceWorker.register('/sw.js').catch(()=>{});matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applyTheme)}catch(error){root.innerHTML=`<div class="auth">${card(`<h1>Verbindung fehlgeschlagen</h1><p>${esc(error.message)}</p>${button('Erneut versuchen','reload','','')}`)}</div>`}}start();
